good_example:
router.get('/proxy', async (req, res) => {
  const target = new URL(String(req.query.url));
  if (!allowedHosts.has(target.hostname)) throw new Error('blocked host');
  const body = await axios.get(target.toString(), { timeout: 3000, maxRedirects: 0 });
  res.send(body.data);
});

